$yangtonifyquestions = [
    [$yangtonifytext('What are the indications for herbs that tonify Yang?','¿Cuáles son las indicaciones de las hierbas que tonifican Yang?'),$yangtonifytext('They primarily treat Kidney-Yang deficiency: cold/sore back, cold intolerance, frequent urination, sexual or reproductive dysfunction, developmental weakness and deep slow weak pulse. Secondary routes include Spleen diarrhea, Lung-Kidney breathing, edema and weak will.','Tratan principalmente deficiencia de Yang de Riñón: espalda fría/dolorida, intolerancia al frío, orina frecuente, disfunción sexual/reproductiva, debilidad de desarrollo y pulso profundo lento/débil. Rutas secundarias: diarrea de Bazo, respiración Pulmón-Riñón, edema y voluntad débil.')],
    [$yangtonifytext('What are the characteristics of herbs that tonify Yang?','¿Cuáles son las características de las hierbas que tonifican Yang?'),$yangtonifytext('Most are sweet and warm, enter Kidney and often Liver/Spleen, and build Yang through Essence rather than merely forcing heat. Many also strengthen bones, nourish Liver Blood, stabilize leakage or treat Wind-Damp Bi.','La mayoría son dulces/tibias, entran en Riñón y a menudo Hígado/Bazo, y construyen Yang mediante Esencia en vez de solo forzar calor. Muchas fortalecen huesos, nutren Sangre, estabilizan pérdidas o tratan Bi.')],
    [$yangtonifytext('What is the difference between warming Yang and tonifying Yang?','¿Cuál es la diferencia entre calentar Yang y tonificar Yang?'),$yangtonifytext('Warm-Interior herbs such as Fu Zi act quickly, pungently and strongly to activate function and expel Cold but can consume Yin. Yang tonics are sweet-warm, slower and steadier; they improve quantity/quality of Yang and often replenish Essence.','Las hierbas que calientan Interior como Fu Zi actúan rápido, acre y fuerte para activar y expulsar Frío, pero pueden consumir Yin. Las tónicas de Yang son dulce-tibias, lentas/sostenidas; mejoran cantidad/calidad de Yang y suelen reponer Esencia.')],
    [$yangtonifytext('How do Xian Mao, Ba Ji Tian and Yin Yang Huo differ?','¿Cómo se diferencian Xian Mao, Ba Ji Tian y Yin Yang Huo?'),$yangtonifytext('Xian Mao is hottest, toxic and strongest for expelling Cold, but weakest for true building. Ba Ji Tian is gentlest and best for steady Kidney-Yang tonification without harsh drying. Yin Yang Huo lies between them for warmth and adds Wind-Damp, numbness and sexual clues.','Xian Mao es la más caliente/tóxica y fuerte para expulsar Frío, pero la más débil para construir. Ba Ji Tian es la más suave y mejor tónica sostenida sin secar. Yin Yang Huo queda entre ambas y añade Viento-Humedad, entumecimiento y sexualidad.')],
    [$yangtonifytext('How do Du Zhong, Xu Duan, Gou Ji and Sang Ji Sheng differ in strengthening bones?','¿Cómo se diferencian Du Zhong, Xu Duan, Gou Ji y Sang Ji Sheng al fortalecer huesos?'),$yangtonifytext('Du Zhong, the current-list herb, most strongly tonifies Kidney and supports low back/pregnancy. Outside this list: Xu Duan emphasizes trauma and reconnecting injury, Gou Ji is warmer for chronic Wind-Damp Bi, and Sang Ji Sheng is gentlest and adds Blood tonification.','Du Zhong, de lista actual, tonifica Riñón con mayor fuerza y apoya espalda/embarazo. Fuera de lista: Xu Duan enfatiza trauma, Gou Ji es más tibia para Bi crónico y Sang Ji Sheng es más suave y nutre Sangre.')],
    [$yangtonifytext('How do Bu Gu Zhi, Tu Si Zi, Sha Yuan Zi and Rou Cong Rong differ?','¿Cómo se diferencian Bu Gu Zhi, Tu Si Zi, Sha Yuan Zi y Rou Cong Rong?'),$yangtonifytext('Current-list Tu Si Zi is neutral, balanced and stabilizes Essence, vision, urine and diarrhea. Rou Cong Rong gently supplements Yang/Essence and moistens bowel. Outside this list: Bu Gu Zhi is hottest for Ming Men, diarrhea and Lung grasping; Sha Yuan Zi binds Essence more strongly and brightens eyes.','Tu Si Zi es neutra/equilibrada y estabiliza Esencia, visión, orina y diarrea. Rou Cong Rong suplementa suavemente y humedece intestino. Fuera de lista: Bu Gu Zhi es más caliente para Ming Men/diarrea/captar Pulmón; Sha Yuan Zi contiene más Esencia y mejora ojos.')],
];
