<section class="single-herbs-guide__section" aria-labelledby="topic-twentyfive-foundations"><h4 id="topic-twentyfive-foundations"><?php echo s($yangtonifytext('Herbs that tonify Yang: general introduction','Hierbas que tonifican Yang: introducción general'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($yangtonifytext('Start with the target, not the word “Yang”: Essence/sexual function, bones/trauma, Bladder leakage, Spleen diarrhea, chronic Lung deficiency or dry bowel. Then choose how warm, building or astringent the herb should be.','Empieza por el objetivo, no por la palabra “Yang”: Esencia/sexualidad, huesos/trauma, pérdida de Vejiga, diarrea de Bazo, Pulmón crónico o intestino seco. Luego elige cuánto calor, construcción o astringencia necesita.'));?></p><div class="single-herbs-guide__decision"><div><strong><?php echo s($yangtonifytext('Essence / sexuality','Esencia / sexualidad'));?></strong><span>Lu Rong · Ba Ji Tian · Yin Yang Huo</span></div><div><strong><?php echo s($yangtonifytext('Bones / trauma','Huesos / trauma'));?></strong><span>Du Zhong · Gu Sui Bu</span></div><div><strong><?php echo s($yangtonifytext('Leakage / diarrhea','Pérdidas / diarrea'));?></strong><span>Tu Si Zi · Yi Zhi Ren</span></div><div><strong><?php echo s($yangtonifytext('Lung / bowel','Pulmón / intestino'));?></strong><span>Dong Chong Xia Cao · Rou Cong Rong · Suo Yang</span></div></div><aside class="single-herbs-guide__memory-path"><p class="single-herbs-guide__memory-line"><?php echo s($yangtonifytext('Enter the Kidney repair workshop.','Entra al taller de reparación del Riñón.'));?></p><p><?php echo s($yangtonifytext('Lu Rong runs the Essence crane. Du Zhong is the back brace; Gu Sui Bu repairs fractures. Tu Si Zi ties four leakage knots while Yi Zhi Ren closes three cold faucets. Rou Cong Rong and Suo Yang oil the bowel track. Dong Chong Xia Cao connects Kidney battery to Lung bellows. Ba Ji Tian is the gentle coach; Yin Yang Huo gives wings; Xian Mao is the toxic torch.','Lu Rong maneja la grúa de Esencia. Du Zhong es la faja y Gu Sui Bu repara fracturas. Tu Si Zi ata cuatro nudos e Yi Zhi Ren cierra tres grifos fríos. Rou Cong Rong y Suo Yang aceitan intestino. Dong Chong Xia Cao conecta batería de Riñón con fuelle de Pulmón. Ba Ji Tian es entrenadora suave; Yin Yang Huo da alas; Xian Mao es antorcha tóxica.'));?></p></aside><p class="single-herbs-guide__safety"><strong><?php echo s($yangtonifytext('Heat boundary:','Límite de Calor:'));?></strong> <?php echo s($yangtonifytext('Do not mistake Yin-deficiency Heat, Damp-Heat or acute inflammation for Yang deficiency. Xian Mao is toxic; Lu Rong is a potent regulated animal product; both require particular professional control.','No confundas Calor por deficiencia de Yin, Humedad-Calor o inflamación aguda con deficiencia de Yang. Xian Mao es tóxica; Lu Rong es producto animal potente/regulado; ambas requieren control profesional especial.'));?></p><ol class="single-herbs-guide__category-herbs"><?php foreach($yangtonifyherbs as $h):?><li class="single-herbs-guide__category-herb single-herbs-guide__category-herb--core"><div class="single-herbs-guide__category-herb-head"><strong><?php echo s($h['name']);?></strong><em><?php echo s($h['latin']);?></em><span class="single-herbs-guide__category-herb-badge"><?php echo s($yangtonifytext('Current category list','Lista vigente de la categoría'));?></span></div><p><?php echo s($h['identity']);?></p></li><?php endforeach;?></ol></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyfive-yang"><h4 id="topic-twentyfive-yang"><?php echo s($yangtonifytext('Yang comparative fingerprints','Huellas comparativas de Yang'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($yangtonifytext('Relative study indices—not doses or efficacy percentages. Values come directly from Yang figures 14.14–14.19; only exact current-list entries are graphed.','Índices relativos de estudio—no dosis ni porcentajes. Valores directos de figuras 14.14–14.19 de Yang; solo entradas exactas de la lista actual.'));?></p><div class="single-herbs-guide__yang-charts"><?php foreach($yangtonifycharts as $chart):?><article class="single-herbs-guide__yang-chart"><h5><?php echo s($chart[0]);?></h5><small><?php echo s($chart[1]);?></small><?php foreach($chart[2] as $name=>$value):?><div class="single-herbs-guide__yang-bar"><span><?php echo s($name);?></span><span class="single-herbs-guide__yang-bar-track"><span class="single-herbs-guide__yang-bar-fill" style="width:<?php echo(int)$value;?>%"></span></span><b><?php echo(int)$value;?></b></div><?php endforeach;?></article><?php endforeach;?></div><p class="single-herbs-guide__yang-note"><strong><?php echo s($yangtonifytext('Reading the ties:','Cómo leer los empates:'));?></strong> <?php echo s($yangtonifytext('Rou Cong Rong and Suo Yang both score 100 for bowel moisture, so choose by gentleness versus stronger sinew/Essence support. Tu Si Zi and Yi Zhi Ren both score 70 for stabilizing Essence, but Yi Zhi Ren dominates cold urine/saliva/diarrhea.','Rou Cong Rong y Suo Yang empatan en 100 para humedecer; elige suavidad frente a mayor apoyo de tendones/Esencia. Tu Si Zi e Yi Zhi Ren empatan en 70 para estabilizar Esencia, pero Yi Zhi Ren domina orina/saliva/diarrea frías.'));?></p></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyfive-profiles"><h4 id="topic-twentyfive-profiles"><?php echo s($yangtonifytext('Individual herb profiles','Perfiles individuales de las hierbas'));?></h4><div class="single-herbs-guide__profiles"><?php foreach($yangtonifyherbs as $h):?><details class="single-herbs-guide__profile"<?php echo $h['name']==='Lu Rong'?' open':'';?>><summary><span class="single-herbs-guide__profile-name"><?php echo s($h['name']);?></span><span class="single-herbs-guide__profile-latin"><?php echo s($h['latin']);?></span><span class="single-herbs-guide__profile-meta"><?php echo s($h['properties']);?> · <?php echo s($h['channels']);?></span></summary><div class="single-herbs-guide__profile-body"><dl><dt><?php echo s($yangtonifytext('Study dose','Dosis de estudio'));?></dt><dd><?php echo s($h['dose']);?></dd><dt><?php echo s($yangtonifytext('Identity','Identidad'));?></dt><dd><?php echo s($h['identity']);?></dd><dt><?php echo s($yangtonifytext('Exam clue','Pista de examen'));?></dt><dd><?php echo s($h['clue']);?></dd><dt><?php echo s($yangtonifytext('Memory','Memoria'));?></dt><dd class="single-herbs-guide__profile-memory"><?php echo s($h['memory']);?></dd><dt><?php echo s($yangtonifytext('Unique fingerprint','Huella única'));?></dt><dd><?php echo s($h['unique']);?></dd><dt><?php echo s($yangtonifytext('Formula boundary','Límite de fórmulas'));?></dt><dd class="single-herbs-guide__profile-formulas"><?php echo s($yangtonifytext('No chief or co-chief role in the current 63-formula Board roster.','No tiene papel principal ni coprincipal en el listado Board vigente de 63 fórmulas.'));?></dd><dt><?php echo s($yangtonifytext('Safety','Seguridad'));?></dt><dd class="single-herbs-guide__profile-safety"><?php echo s($h['caution']);?></dd></dl></div></details><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyfive-comparisons"><h4 id="topic-twentyfive-comparisons"><?php echo s($yangtonifytext('High-yield comparisons','Comparaciones de alto rendimiento'));?></h4><div class="single-herbs-guide__comparisons"><?php foreach($yangtonifycomparisons as $c):?><?php $url=new moodle_url($ises?$c[1]:$c[0],['from'=>'single-herbs','focus'=>(string)$selected['number']]);?><a class="single-herbs-guide__comparison" href="<?php echo $url->out(false);?>"><strong><?php echo s($c[2]);?></strong><span><?php echo s($c[3]);?></span><small><?php echo s($yangtonifytext('Open full comparison →','Abrir comparación completa →'));?></small></a><?php endforeach;?></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyfive-questions"><h4 id="topic-twentyfive-questions"><?php echo s($yangtonifytext('Yang questions shown in full','Preguntas de Yang mostradas completas'));?></h4><p class="single-herbs-guide__section-lead"><?php echo s($yangtonifytext('Chapter 14 questions 31–36 define this Yang-tonic category. Outside-list herbs are explicitly identified in the answers.','Las preguntas 31–36 del capítulo 14 definen esta categoría. Las hierbas fuera de lista se identifican expresamente en las respuestas.'));?></p><div class="single-herbs-guide__yang-deck" data-yang-deck data-card-label="<?php echo s($yangtonifytext('Card','Tarjeta'));?>" data-of-label="<?php echo s($yangtonifytext('of','de'));?>"><?php foreach($yangtonifyquestions as $i=>$q):?><article class="single-herbs-guide__yang-card<?php echo $i===0?' is-active':'';?>" data-yang-card aria-hidden="<?php echo $i===0?'false':'true';?>"><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--front"><span class="single-herbs-guide__yang-label"><?php echo s($yangtonifytext('Question','Pregunta'));?> <?php echo$i+1;?> <?php echo s($yangtonifytext('of','de'));?> <?php echo count($yangtonifyquestions);?> · Yang, <?php echo s($yangtonifytext('Chapter','capítulo'));?> 14</span><p class="single-herbs-guide__yang-question"><?php echo s($q[0]);?></p></div><div class="single-herbs-guide__yang-face single-herbs-guide__yang-face--back"><span class="single-herbs-guide__yang-label"><?php echo s($yangtonifytext('Answer','Respuesta'));?> <?php echo$i+1;?></span><p class="single-herbs-guide__yang-answer"><?php echo s($q[1]);?></p></div></article><?php endforeach;?><div class="single-herbs-guide__yang-controls"><button class="single-herbs-guide__yang-control" type="button" data-yang-prev>← <?php echo s($yangtonifytext('Previous','Anterior'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--flip" type="button" data-yang-flip data-show-label="<?php echo s($yangtonifytext('Show answer','Mostrar respuesta'));?>" data-hide-label="<?php echo s($yangtonifytext('Show question','Mostrar pregunta'));?>"><?php echo s($yangtonifytext('Show answer','Mostrar respuesta'));?></button><button class="single-herbs-guide__yang-control single-herbs-guide__yang-control--next" type="button" data-yang-next><?php echo s($yangtonifytext('Next','Siguiente'));?> →</button></div><p class="single-herbs-guide__yang-progress" data-yang-progress><?php echo s($yangtonifytext('Card','Tarjeta'));?> 1 <?php echo s($yangtonifytext('of','de'));?> <?php echo count($yangtonifyquestions);?></p></div></section>

<section class="single-herbs-guide__section" aria-labelledby="topic-twentyfive-recall"><h4 id="topic-twentyfive-recall"><?php echo s($yangtonifytext('Quick recall','Repaso rápido'));?></h4><div class="single-herbs-guide__recall"><details><summary><?php echo s($yangtonifytext('Strong animal-derived Essence, Blood and bone builder?','¿Constructora animal fuerte de Esencia, Sangre y hueso?'));?></summary><p><strong>Lu Rong.</strong></p></details><details><summary><?php echo s($yangtonifytext('Warm Kidney and moisten dry bowel gently?','¿Calentar Riñón y humedecer intestino suavemente?'));?></summary><p><strong>Rou Cong Rong.</strong></p></details><details><summary><?php echo s($yangtonifytext('Pregnancy low-back support versus fracture repair?','¿Apoyo lumbar en embarazo frente a reparación de fractura?'));?></summary><p><strong>Du Zhong</strong> / <strong>Gu Sui Bu.</strong></p></details><details><summary><?php echo s($yangtonifytext('Neutral four-way stabilizer?','¿Estabilizadora neutra de cuatro vías?'));?></summary><p><strong>Tu Si Zi.</strong></p></details><details><summary><?php echo s($yangtonifytext('Three cold faucets: urine, saliva and stool?','¿Tres grifos fríos: orina, saliva y heces?'));?></summary><p><strong>Yi Zhi Ren.</strong></p></details><details><summary><?php echo s($yangtonifytext('Kidney–Lung bridge for chronic cough and depletion?','¿Puente Riñón–Pulmón para tos crónica y agotamiento?'));?></summary><p><strong>Dong Chong Xia Cao.</strong></p></details><details><summary><?php echo s($yangtonifytext('Hottest toxic torch versus gentlest steady coach?','¿Antorcha tóxica más caliente frente a entrenadora suave?'));?></summary><p><strong>Xian Mao</strong> / <strong>Ba Ji Tian.</strong></p></details></div></section>

